function integrityIssues(){const st=stateNow(),all=jobs(),byJob=new Map(),issues=[];for(const j of all){if(!j?.no)continue;const k=norm(j.no);if(!k)continue;if(byJob.has(k))issues.push({type:'DUPLICATE_JOB_CARD',job:j.no,detail:'Duplicate Job Card number'});else byJob.set(k,j)}const known=k=>k==='id001'||byJob.has(k);for(const a of st.assign||[]){const k=norm(a?.job);if(k&&!known(k))issues.push({type:'ORPHAN_ASSIGNMENT',job:a.job,detail:'Assignment references a missing Job Card'})}for(const s of st.sessions||[]){const k=norm(s?.job);if(k&&!known(k))issues.push({type:'ORPHAN_SESSION',job:s.job,detail:'Work session references a missing Job Card'})}const cc=st.consumables||{};for(const x of [...(cc.issues||[]),...(cc.actuals||[])]){const k=norm(x?.jobCard);if(k&&!known(k))issues.push({type:'ORPHAN_CONSUMABLE',job:x.jobCard,detail:'Consumable entry references a missing Job Card'})}return issues}
