function leaveSummary(){const rows=(state.leaves||[]).filter(l=>l&&!l.cancelled),now=new Date(),today=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0'),prefix=today.slice(0,7)+'-';const people=x=>new Set(x.map(l=>String(l.emp))).size;return {today:people(rows.filter(l=>String(l.date||'')===today)),month:people(rows.filter(l=>String(l.date||'').startsWith(prefix)))};}
