function ensurePanel(){if(!allowed())return;const root=document.getElementById(role()==='Supervisor'?'supervisorView':'managerView');if(!root||root.classList.contains('hidden'))return;let panel=root.querySelector('[data-workshop-panel]');if(panel)return;panel=document.createElement('section');panel.className='card workshop-overview';panel.dataset.workshopPanel='1';const supervisorControls=role()==='Supervisor'?'<div class="wo-supervisor-find"><div class="wo-find-title">Find Job Card</div><div class="wo-find-search"><input id="woSupervisorQuickSearch" type="search" aria-label="Find Job Card" placeholder="JC / Reg / Vehicle" autocomplete="off"><button type="button" data-workshop-action="search-inline">SEARCH</button></div></div>':'<div class="wo-manager-quick"><div class="wo-heading"><div><h3>Job Card Search</h3><small>Search Job Card, registration, or vehicle and open complete details</small></div></div><div class="wo-tools wo-manager-search-only">'+button('Search Job Card','search')+'</div></div>';panel.innerHTML=supervisorControls+(role()==='Manager'?'<div id="woDailySummary">'+summaryHtml()+'</div>':'');removeManagerSummaryReady();if(role()==='Manager'){const identity=root.querySelector('.v91-role-identity');if(identity?.parentNode===root)identity.insertAdjacentElement('afterend',panel);else root.prepend(panel)}else{const identity=root.querySelector('.v91-role-identity');if(identity?.parentNode===root)identity.insertAdjacentElement('afterend',panel);else root.prepend(panel)}if(role()==='Supervisor')document.querySelectorAll('[data-v143-unassigned-count]').forEach(b=>{const value=String(queue().length);if(b.textContent!==value)b.textContent=value});}
