function installVoiceReview(){const prior=window.v143ApplyVoiceEntry;if(typeof prior!=='function'||prior.workshopReview)return;const wrapped=function(text){if(role()!=='Supervisor')return prior.apply(this,arguments);const before=Object.fromEntries(fields.map(([id])=>[id,document.getElementById(id)?.value||'']));const result=prior.apply(this,arguments);if(!String(text||'').trim())return result;voiceDraft={before};shell('Review Voice Entry','<p>'+esc(text)+'</p><p class="muted">Check every field. You can correct the details below. Nothing is saved until you use a Create button on Quick Entry.</p>'+fields.map(([id,label])=>{const el=document.getElementById(id);return '<label>'+label+(id==='se'?'<select id="woVoice_'+id+'"><option value="">Assign later</option>'+Array.from(el?.options||[]).filter(o=>o.value).map(o=>'<option value="'+esc(o.value)+'"'+(o.value===el.value?' selected':'')+'>'+esc(o.textContent)+'</option>').join('')+'</select>':'<input id="woVoice_'+id+'" value="'+esc(el?.value||'')+'">')+'</label>'}).join('')+'<div class="wo-tools">'+button('Discard voice changes','voice-cancel')+button('Use reviewed details','voice-accept')+'</div>');return result};wrapped.workshopReview=true;window.v143ApplyVoiceEntry=wrapped;}
