const css=document.createElement('style');css.textContent='.workshop-overview{border:1px solid #dce5ee!important;border-radius:16px!important;padding:16px!important;background:#fff;color:#21354b}.wo-heading,.wo-tools,.wo-row,.wo-nav{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap}.wo-nav{justify-content:flex-end}.wo-nav button:first-child{background:#e8f1fb;color:#173c64}.wo-nav button:last-child{background:#fee2e2;border-color:#fecaca;color:#991b1b}.wo-heading h3{margin:0 0 5px}.wo-manager-quick{padding-bottom:10px;margin-bottom:12px;border-bottom:1px solid #e5edf4}.wo-manager-quick .wo-heading small{font-size:11px}.wo-tools{justify-content:flex-start;margin:10px 0}.workshop-overview button{min-height:44px;border:1px solid #cbdbea;border-radius:10px;background:#eef5fc;color:#173c64;padding:10px 14px;font-weight:700}.wo-row{padding:12px 0;border-bottom:1px solid #e5edf4}.wo-row span{display:block;font-size:13px;margin-top:4px}.wo-list-row{display:grid;grid-template-columns:24px minmax(0,1fr) auto;gap:6px;align-items:center;padding:6px 7px;margin:4px 0;border:1px solid #e1e8ef;border-radius:9px;background:linear-gradient(145deg,#fff,#f8fafc);box-shadow:0 1px 4px rgba(15,23,42,.05)}.wo-row-no{display:grid;place-items:center;width:22px;height:22px;border-radius:6px;background:#edf4fb;color:#31577d;font-size:9px}.wo-row-actions{display:flex;gap:4px;flex-wrap:nowrap}.workshop-overview .wo-row-actions button{min-height:32px;padding:4px 7px;font-size:9px;border-radius:7px}@media(max-width:520px){.workshop-overview{padding:10px!important}.wo-list-row{grid-template-columns:22px minmax(0,1fr) auto;padding:5px}.wo-list-row span{font-size:9px;margin-top:1px}.wo-row-actions button{min-width:0!important}.wo-row-actions button:nth-child(2){padding-left:5px!important;padding-right:5px!important}}.wo-unassigned{display:grid!important;grid-template-columns:1fr auto!important;grid-template-rows:auto auto!important;text-align:left!important;background:#fff7ed!important;border-color:#fdba74!important;color:#9a3412!important}.wo-unassigned span{font-weight:800}.wo-unassigned strong{grid-column:2;grid-row:1/3;align-self:center;font-size:24px}.wo-unassigned small{grid-column:1;color:#9a3412!important}.wo-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin:14px 0}#managerView .workshop-overview .wo-stats button,#managerView .workshop-overview .wo-tools button{display:flex;align-items:center;gap:8px;text-align:left}#managerView .wo-card-icon{display:grid;place-items:center;flex:0 0 27px;width:27px;height:27px;border-radius:9px;background:#e8f3ff;color:#1473d2;font-size:15px;font-weight:1000;box-shadow:inset 0 1px 2px #fff,0 2px 5px #17324b14}#managerView .wo-icon-paused{background:#fff3dc;color:#e58a00}#managerView .wo-icon-leave-today{position:relative;background:#ffe8ef;color:#db2777}#managerView .wo-today-leave-card:has(.wo-leave-badge){background:linear-gradient(145deg,#fff7fa,#fff0f5);border-color:#ffc4d6}#managerView .wo-leave-badge{position:absolute;right:-7px;top:-7px;display:grid;place-items:center;min-width:17px;height:17px;padding:0 3px;border-radius:999px;background:#e11d48;color:#fff;font-size:9px;line-height:1;font-weight:1000;box-shadow:0 1px 3px #88133740}#managerView .wo-icon-leave-month{background:#f1e9ff;color:#7c3aed}#managerView .wo-icon-ready{background:#e7f8ef;color:#0f9f64}#managerView .wo-icon-delayed,#managerView .wo-icon-attention{background:#ffe9e9;color:#dc2626}#managerView .wo-icon-waiting{background:#e9f3ff;color:#2563eb}#managerView .wo-icon-pending{background:#f1e9ff;color:#7e22ce}.wo-status-list{display:grid;gap:6px;margin-top:8px}.wo-status-row{display:grid;grid-template-columns:24px minmax(0,1fr) auto;align-items:center;gap:7px;min-height:38px;padding:5px 7px;border:1px solid #dce6f0;border-radius:10px;background:#fbfdff;box-shadow:0 2px 6px #17324b0d}.wo-status-no{display:grid;place-items:center;width:22px;height:22px;border-radius:6px;background:#edf4fb;color:#31577d;font-size:9px}.wo-status-name{min-width:0;font-weight:850;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wo-status-job{justify-self:end;white-space:nowrap;border:1px solid #bfd0e2;border-radius:999px;padding:3px 7px;background:#f4f8fc;color:#294b6c!important;font-size:10px!important;font-weight:850}.wo-status-denter .wo-status-name{color:#5b21b6}.wo-status-painter .wo-status-name{color:#c2410c}.wo-status-mechanic .wo-status-name{color:#1d4ed8}#managerView .wo-card-label{min-width:0}.workshop-overview label{display:block;margin:10px 0}.workshop-overview input,.workshop-overview select{width:100%;box-sizing:border-box;min-height:44px}.workshop-overview small{color:#64748b}#supervisorView .wo-supervisor-find{display:block}#supervisorView .wo-find-title{margin:0 0 6px 2px;font-size:13px;font-weight:900;color:#172033}#supervisorView .wo-find-search{min-height:46px;border-radius:12px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px;align-items:center}#supervisorView .wo-find-search input{width:100%;min-width:0;height:46px;margin:0}#supervisorView .wo-find-search button{height:46px;margin:0;padding:0 10px}@media(max-width:420px){#supervisorView .wo-find-search button{font-size:8px;padding:0 9px}}#managerView .wo-manager-search-only{display:grid;grid-template-columns:1fr;gap:10px}.workshop-overview button[data-workshop-action="detail-360"]{background:linear-gradient(145deg,#0ea5a8,#1677c8)!important;color:#fff!important;border:1px solid #0b6fae!important;border-radius:10px!important;font-weight:900!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 3px 0 #0b6597,0 7px 12px rgba(14,116,144,.20)!important}.workshop-overview button[data-workshop-action="detail-360"] .wo-card-label{color:#fff!important}.workshop-overview button[data-workshop-action="detail-360"]:active{transform:translateY(2px)}.wo-360-card{margin:10px 0;padding:12px;border:1px solid #dce6f0;border-radius:14px;background:linear-gradient(145deg,#fff,#f8fbff);box-shadow:0 5px 14px rgba(15,23,42,.07)}.wo-360-card>h4{margin:0 0 9px;padding-bottom:7px;border-bottom:1px solid #e6edf5;color:#173c64;font-size:13px}.wo-360-card .wo-stats{margin:0}.wo-360-card .wo-row{padding:8px 0}.wo-360-card .wo-row:last-child{border-bottom:0}.wo-360-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;align-items:start}.wo-360-grid>.wo-360-card{margin:0;height:100%;box-sizing:border-box}.wo-360-hero{border-color:#b9d8f4;background:linear-gradient(145deg,#f7fbff,#eef7ff)}.wo-360-cost{padding:10px;border-radius:14px;background:linear-gradient(145deg,#f8fbff,#f1f7fc);border:1px solid #d8e6f2}.wo-360-cost button{min-height:50px!important;border-radius:11px!important;justify-content:center!important;text-align:center!important}.wo-360-production{padding:10px;border-radius:14px;background:linear-gradient(145deg,#fff,#f7fafc);border:1px solid #e1e8ef}@media(max-width:620px){.wo-360-grid{grid-template-columns:1fr}.wo-360-card{padding:10px}.wo-360-card .wo-stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.wo-360-card .wo-stats>b,.wo-360-card .wo-stats>button{font-size:10px;min-width:0;overflow-wrap:anywhere}}';document.head.appendChild(css);
let scheduled=false;const schedule=()=>{if(scheduled)return;scheduled=true;setTimeout(()=>{scheduled=false;ensurePanel();installVoiceReview()},0)};new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});schedule();setInterval(()=>{if(role()==='Manager'){const box=document.getElementById('woDailySummary');if(box){const html=summaryHtml();if(box.innerHTML!==html)box.innerHTML=html;removeManagerSummaryReady()}}if(role()==='Supervisor'){document.querySelectorAll('[data-v143-unassigned-count]').forEach(b=>{const value=String(queue().length);if(b.textContent!==value)b.textContent=value})}},5000);
window.zukaitOpenJob360=function(no){setTimeout(()=>{try{detail(no)}catch(err){console.error('Job Card 360 failed',err);shell('Job Card '+no+' — 360° View','<div class="notice"><b>Basic Job Card opened, but one full-detail section failed.</b><br>'+esc(err?.message||String(err))+'</div>')}},0)};window.zukaitJob360Ready=true;window.zukaitWorkshopOverview={unassigned,search,summary,integrityIssues,openSearch,detail,refresh};
